SELECT CASE WHEN stores.region IN ('North', 'Central') THEN 'priority' ELSE 'other' END AS region_group, MAX(store_sales.units) AS max_units FROM store_sales RIGHT JOIN products ON store_sales.product_id = products.id LEFT JOIN stores ON store_sales.store_id = stores.id WHERE store_sales.product_id IN (1, 4) GROUP BY CASE WHEN stores.region IN ('North', 'Central') THEN 'priority' ELSE 'other' END;
